import React from 'react';
import { Link } from 'react-router-dom';
import { Navbar, Nav, Container } from 'react-bootstrap';
import 'animate.css'; // Animation library
import './Navbar.css'; // Custom styles

function NavbarComponent() {
  return (
    <Navbar bg="dark" variant="dark" expand="lg" className="animate__animated animate__fadeIn">
      <Container>
        <Navbar.Brand href="/">Comics World</Navbar.Brand>
        <Navbar.Toggle aria-controls="basic-navbar-nav" />
        <Navbar.Collapse id="basic-navbar-nav">
          <Nav className="ms-auto">
            <Nav.Link as={Link} to="/" className="nav-item">
              Home
            </Nav.Link>
            <Nav.Link as={Link} to="/comics" className="nav-item">
              Comics
            </Nav.Link>
          </Nav>
        </Navbar.Collapse>
      </Container>
    </Navbar>
  );
}

export default NavbarComponent;
